import type { Curriculum } from './workshop-content';
import type { LessonStep, WorkshopLesson } from '../content/workshop/types';
import { cinemaCameraLabs } from './workshop-ai-cinema-cameras';
import { cinemaYaml } from './workshop-ai-cinema-yaml';

type Pair = readonly [string, string];
const classroom = 'https://www.skool.com/idall-lite-1529/classroom/11b0205e';
const sources = ['47f8151a396146d7a4945cb15188ad98', '96ebd428092a4301a43112f182c4b69f', '8d4cb54670cf44e89444dd0a0b810ecd', '864c2b183de34f149d646be15840d272', '61e4b345a3354de59677a93d37d31543', '7b07873ca4b14b49bb3b646c001df204', '46a75bfc04ac4db99f6b9d13439de054'];
export const cinemaLessonNumbers = [7, 8, 9, 10, 11, 12, 13] as const;

export function aiCinemaCurriculum(locale: 'vi' | 'en'): Curriculum {
  const t = (vi: string, en: string) => locale === 'vi' ? vi : en;
  const pick = (pair: Pair) => t(...pair);
  const note = t('Prompt thực hành do GenYZ biên soạn theo phương pháp của bài nguồn; cả hai ngôn ngữ chưa chạy thử. Kết quả mô tả là tiêu chí cần đạt, không phải video đã tạo.', 'GenYZ-authored practice prompt following the source method; neither language has been run. Described outcomes are review targets, not generated results.');
  const step = (title: Pair, instruction: Pair, tool: string, save: string, prompt?: Pair, kind: LessonStep['promptKind'] = 'planning'): LessonStep => ({
    title: pick(title), instruction: pick(instruction), tool, save,
    ...(prompt ? { prompt: prompt[1], promptVi: prompt[0], promptLanguage: 'en' as const, promptKind: kind, promptEvidence: note } : {}),
  });
  const source = (index: number, text: Pair): WorkshopLesson['example'] => ({
    title: t(`Đối chiếu bài nguồn · Lesson ${index + 7}`, `Source comparison · Lesson ${index + 7}`), text: pick(text), href: `${classroom}?md=${sources[index]}`,
  });
  const notes = t('Sổ thực hành', 'Workbook');
  const character: Pair = [
    'Tạo ảnh toàn thân nhân vật hư cấu tên An, người Việt trưởng thành, tóc đen ngắn, mũ bảo hiểm ngọc lam, áo khoác màu kem, quần xám than, giày trắng. Đứng thẳng cạnh ván trượt màu gỗ có bánh đen. Nền xám đơn giản, ánh sáng mềm. Thấy đủ bàn tay, bàn chân, mũ và ván. Tỷ lệ tự nhiên; không chữ, không logo. Dùng ảnh này để chốt nhận diện trước khi dựng cảnh.',
    'Create a full-body image of An, a fictional Vietnamese adult with short black hair, a teal helmet, cream jacket, charcoal trousers and white shoes. An stands beside a wood-colored skateboard with black wheels. Simple gray background, soft light. Show hands, feet, helmet and board completely. Natural proportions; no text or logos. Establish this identity before building the scene.',
  ];
  const lessons: WorkshopLesson[] = [
    {
      id: 'story', goal: t('Làm một chuỗi sáu shot rõ ràng theo bốn bước: viết kịch bản, tạo nhân vật, phác storyboard, rồi dựng frame điện ảnh.', 'Build a clear six-shot sequence in four stages: script, character, sketch storyboard, then cinematic frames.'),
      terms: t('Storyboard là bản phân cảnh bằng hình. Blocking cho biết nhân vật đứng ở đâu và làm gì trong cảnh. Node là một khối công việc trong Freepik Spaces; @reference đưa nội dung đã có vào Assistant. Sketch dùng để chốt bố cục, còn render hoàn thiện hình ảnh.', 'A storyboard is a visual plan for the shots. Blocking says where a character is and what they do in a scene. A node is a task block in Freepik Spaces; @references bring existing material into an Assistant. Sketches settle the composition, while rendering finishes the image.'),
      input: t('Tạo một Freepik Space mới. Bài thực hành của GenYZ theo An đi lấy ván rồi trượt trên đường ven biển vào cuối chiều. Đây là nhân vật và bối cảnh mới của bài tập, không phải bộ ảnh của giảng viên.', 'Create a new Freepik Space. GenYZ’s exercise follows An collecting a skateboard and riding along a coastal road in late afternoon. An and this setting belong to this practice exercise, not to the instructor’s image set.'),
      steps: [
        step(['1 · Viết kịch bản theo shot', '1 · Write the shot-based script'], ['Dùng công cụ chat để chia câu chuyện thành đúng sáu shot. Đưa nội dung vào node văn bản tên script. Mỗi shot ghi cỡ cảnh, vị trí, hành động và điều người xem cần hiểu. Chưa yêu cầu tạo ảnh.', 'Use a chat tool to break the story into exactly six shots. Put the result in a text node named script. Record framing, position, action and the information each shot conveys. Do not generate images yet.'], 'ChatGPT → Freepik Spaces · Text', 'L07-script.txt', [
          'Viết kịch bản sáu shot 16:9 về An lấy ván và bắt đầu chuyến trượt ven biển. Shot 1: toàn cảnh đường và An đến chỗ để ván. Shot 2: trung cảnh An quan sát đường. Shot 3: cận tay nhấc ván. Shot 4: góc thấp thấy chân đặt lên ván. Shot 5: toàn vừa theo ngang khi An bắt đầu trượt. Shot 6: toàn cảnh An đi xa. Mỗi shot có cỡ cảnh, bố cục, hành động, hướng đi và mục đích kể chuyện. Giữ nắng cuối chiều từ trái, biển bên phải. Chỉ trả kịch bản, không tạo ảnh.',
          'Write a six-shot 16:9 script about An collecting a board and beginning a coastal ride. Shot 1: a wide road view as An approaches the board. Shot 2: a medium of An checking the road. Shot 3: a hand close-up lifting the board. Shot 4: a low view of feet stepping onto the board. Shot 5: a medium-wide lateral follow as An starts riding. Shot 6: a wide of An receding. For every shot specify framing, composition, action, travel direction and narrative purpose. Keep late-afternoon light from the left and the sea to the right. Return only the script, not images.',
        ]),
        step(['2 · Chốt nhân vật', '2 · Establish the character'], ['Tạo node Image Generator, chạy prompt nhân vật, chọn ảnh nhìn rõ nhận diện và đặt tên node là character. Kiểm tra trang phục, mũ, tỷ lệ cơ thể và ván trước khi đưa ảnh vào Assistant. Lưu cả ảnh và prompt.', 'Create an Image Generator node, run the character prompt, choose an image where the identity reads clearly and name the node character. Check clothing, helmet, proportions and board before using it in the Assistant. Save the image and prompt.'], 'Freepik · Image Generator', 'L07-character.png + character-prompt.txt', character, 'image'),
        step(['3 · Vẽ storyboard phác thảo', '3 · Build the sketch storyboard'], ['Tạo Assistant, tham chiếu @script và @character bằng trình chọn của Freepik. Yêu cầu một tờ phác thảo đen trắng có sáu ô: ba ô hàng trên, ba ô hàng dưới. Mỗi ô chứa khung ngang 16:9. Đặt tên kết quả sketch. Ưu tiên bố cục và vị trí, chưa thêm chi tiết.', 'Create an Assistant and attach @script and @character using Freepik’s reference picker. Request one black-and-white sheet with three panels across and two rows. Each panel contains a 16:9 frame. Name the result sketch. Prioritize composition and placement over detail.'], 'Freepik · Assistant', 'L07-sketch.png', [
          'Dùng @script để giữ đúng thứ tự sáu shot và @character để giữ nhận diện An. Tạo MỘT tờ storyboard phác chì đen trắng, ba cột và hai hàng, đúng sáu ô. Bên trong từng ô là khung ngang 16:9, có thể thêm khoảng trắng để giữ tỷ lệ. Giữ cỡ cảnh, vị trí, hướng đi và đường chân trời của từng shot. Không thêm shot, không ghép hai hành động khác nhau vào một ô. Nét thô, hình dáng dễ đọc, không chữ hay logo.',
          'Use @script for the exact six-shot order and @character for An’s identity. Create ONE black-and-white pencil storyboard sheet, three columns by two rows, exactly six panels. Each panel contains a horizontal 16:9 image; use margins where needed to preserve that ratio. Retain shot size, placement, direction and horizon for each shot. Add no shots and do not combine different shots in one panel. Rough lines, readable silhouettes, no text or logos.',
        ], 'image'),
        step(['4 · Chuyển phác thảo thành frame điện ảnh', '4 · Translate sketches into cinematic frames'], ['Tạo Assistant thứ hai, nối @sketch và @character. Sketch chỉ quyết định bố cục; character chỉ quyết định nhận diện. Yêu cầu sáu ảnh riêng, mỗi ảnh một shot. Nếu công cụ trả một bảng ghép, yêu cầu lại từng shot; đừng coi bảng ghép là sáu file riêng.', 'Create a second Assistant connected to @sketch and @character. The sketch controls composition; character controls identity. Request six separate images, one per shot. If the tool returns a grid, request individual shots; a grid is not six separate files.'], 'Freepik · Assistant → Image Generator', 'L07-shot-01.png … L07-shot-06.png', [
          'Dùng @sketch làm tham chiếu bố cục, góc máy, vị trí và hướng chuyển động. Dùng @character làm tham chiếu ngoại hình An. Chuyển sáu ô thành sáu ảnh điện ảnh riêng biệt, mỗi ảnh 16:9, một shot mỗi file. Giữ đường chân trời, kích thước chủ thể, khoảng trống, biển bên phải và nắng từ trái; không lật hình. Chất liệu tự nhiên, màu chiều ấm, không chữ hoặc watermark. Không trả contact sheet hay collage. Nếu chỉ tạo được một ảnh mỗi lượt, bắt đầu shot 1 và chờ tôi yêu cầu shot kế.',
          'Use @sketch for composition, camera angle, placement and movement direction. Use @character for An’s appearance. Translate the six panels into six separate cinematic images, each 16:9 and one shot per file. Preserve horizon, subject scale, negative space, sea on the right and light from the left; do not mirror. Natural materials, warm afternoon color, no text or watermark. Do not return a contact sheet or collage. If only one image can be produced per request, start with shot 1 and wait for the next request.',
        ], 'image'),
        step(['5 · Duyệt trước khi tạo chuyển động', '5 · Review before animation'], ['Xếp sáu ảnh theo thứ tự. So từng frame với ô sketch tương ứng: vị trí tay và ván, hướng nhìn, hướng đi, tỷ lệ và ánh sáng. Chỉ sửa shot có lỗi và giữ lại ảnh trước/sau. Viết một câu về vai trò của mỗi shot trong chuỗi, từ việc giới thiệu không gian đến cảnh kết.', 'Arrange the six images in order. Compare each frame with its matching sketch: hand and board placement, eyeline, direction, scale and light. Repair only the shot that fails and keep before/after versions. Write one sentence about what each shot contributes, from establishing the place to the ending.'], notes, 'L07-storyboard-review.txt'),
      ],
      checks: [t('Đủ bốn bước và các node tham chiếu nối đúng vai trò.', 'All four stages are present and references have distinct roles.'), t('Một tờ sketch sáu ô; sáu frame riêng 16:9.', 'One six-panel sketch sheet; six separate 16:9 frames.'), t('Mỗi shot có mục đích và đã kiểm tra tính liên tục.', 'Every shot has a purpose and a continuity check.')],
      troubleshooting: [{ problem: t('Render đổi bố cục hoặc trả sai số ảnh.', 'Rendering changes composition or returns the wrong number of images.'), fix: t('Chỉ rõ ô sketch cần dựng, giữ vai trò từng reference và tạo từng shot. Không sửa toàn bộ chuỗi bằng một yêu cầu mơ hồ.', 'Identify the exact panel, preserve reference roles and render one shot at a time. Avoid a vague request to fix the entire sequence.') }],
      example: source(0, ["Video 5:22 dùng câu chuyện người đàn ông và chiếc xe trong hoang mạc. Bốn bước được giải thích khoảng 1:00-2:40, sau đó phân tích chức năng sáu shot. Video có hiển thị một bảng render ghép dù phần hướng dẫn yêu cầu ảnh riêng; bài thực hành ở đây kiểm tra file đầu ra rõ ràng.", "The 5:22 recording uses a man and a car in a wasteland. The four stages appear around 1:00-2:40, followed by the six shots’ narrative functions. A rendered grid is visible despite the written request for separate images; this exercise checks the actual output files."]),
    },
    {
      id: 'references', goal: t('Dùng lực, thời gian và trọng lượng để chỉ đạo chuyển động, rồi nộp một cảnh cùng prompt và phần giải thích lựa chọn.', 'Use force, time and weight to direct motion, then submit one scene with its prompt and rationale.'),
      terms: t('Force: lực khởi phát. Sequence: thứ tự sự kiện. Secondary motion: chuyển động đi theo hành động chính, như áo, bụi hoặc nước. Human reaction: phản ứng nhìn thấy qua mắt, tay, nhịp thở và tư thế. Con số trong prompt là mục tiêu, không phải phép đo kết quả.', 'Force initiates motion. Sequence orders events. Secondary motion follows the main action, such as clothes, dust or water. Human reaction is visible in eyes, hands, breathing and posture. Numbers in a prompt are targets, not measurements of the output.'),
      input: t('Một frame đã duyệt ở L7. Xem các ví dụ L8 trước khi viết prompt; bài nguồn dùng Seedance 2.0.', 'One approved L7 frame. Study the L8 examples before prompting; the source uses Seedance 2.0.'),
      steps: [
        step(['1 · Quan sát mười ví dụ', '1 · Study the ten examples'], ['Theo đúng thứ tự video: xe máy trong hẻm (helmet cam và hơi thở); xe drift trên đường ướt (thân xe → nước → khói); ba xe trên núi (đồng bộ hành động và cử chỉ vui); phi hành gia (bước nảy và giúp nhau); người bám vách đá (ngón tay trượt, sỏi rơi); người chạy tới nút bấm (vấp → chống lại → nhấn); sóng lớn (quy mô và các lớp va chạm); parkour (chạy → nhảy → tiếp đất → lăn); cận mặt khóc (giọt nước mắt và môi run); ô tô tăng tốc (gia tốc, camera và khói). Với mỗi ví dụ, ghi lực, thứ tự, camera và phản ứng; không chỉ chép tên cảm xúc.', 'Follow the recording’s order: alley motorcycle (helmet cam and breath); wet-road drift (body, water, then smoke); mountain riders (synchronized action and playful gestures); astronauts (bouncing steps and help); cliff hanger (slipping fingers and falling pebbles); runner reaching a button (stumble, recover, press); wave (scale and layered impacts); parkour (run, jump, land, roll); crying close-up (tear and trembling lip); accelerating car (acceleration, camera and smoke). For each, identify force, sequence, camera and reaction rather than merely naming an emotion.'], notes, 'L08-ten-examples.txt'),
        step(['2 · Viết chuỗi nguyên nhân và phản ứng', '2 · Write the cause-and-response chain'], ['Chọn một hành động: An đẩy ván, tăng tốc rồi dừng ở vạch. Ghi cái gì chuyển động trước và cái gì theo sau. Ví dụ lực chân làm ván lăn; thân người cân bằng; vạt áo trễ một nhịp. Chọn hành vi camera trước khi viết prompt.', 'Choose one action: An pushes, gains speed, then stops at a line. Specify what moves first and what follows. Foot force drives the board; the body balances; the jacket follows with a delay. Choose camera behavior before writing the prompt.'], notes, 'L08-motion-map.txt'),
        step(['3 · Viết prompt bốn phần', '3 · Write the four-part prompt'], ['Tải frame lên Seedance. Viết Force → Sequence → Camera → Human reaction; dùng thời gian, khoảng cách hoặc góc khi chúng làm rõ hành động. Không tự đổi model mà vẫn ghi kết quả là Seedance 2.0; lưu phiên bản thật đã chọn.', 'Upload the frame to Seedance. Write Force → Sequence → Camera → Human reaction; use timing, distance or angles when they clarify action. If you use another model version, record it accurately.'], 'Seedance', 'L08-prompt.txt + settings.txt', [
          'Dùng frame An và ván đã tải lên. Cảnh liên tục 6 giây, thời gian thực.\nLực: chân sau đẩy xuống mặt đường một lần làm ván tăng tốc.\nTrình tự: 0–2 giây đẩy rồi đặt cả hai chân lên ván; 2–4 giây trượt về trước, gối hơi chùng, vạt áo theo sau; 4–6 giây hạ chân sau xuống đường để phanh bằng đế giày, giảm tốc và dừng trước vạch trắng.\nCamera: theo ngang êm, giữ khoảng cách, thấy đủ người và ván, không cắt.\nPhản ứng: mắt nhìn vạch, vai thả lỏng dần, thở ra khi dừng. Giữ nhận diện và nắng từ trái. Không tự thêm cú nhảy.',
          'Use the uploaded frame of An and the board. One continuous six-second scene at real-time speed.\nForce: the rear foot pushes once against the road to accelerate the board.\nSequence: 0–2s push and place both feet on the board; 2–4s roll forward with slightly bent knees and delayed jacket movement; 4–6s lower the rear foot to drag the sole on the road, decelerate and stop before a white line.\nCamera: smooth lateral follow at constant distance, showing the full rider and board; no cut.\nHuman reaction: eyes follow the line, shoulders gradually relax, one exhale on stopping. Preserve identity and light from the left. Add no jump.',
        ], 'video'),
        step(['4 · Kiểm tra tốc độ và độ trễ', '4 · Check speed and delays'], ['Xem trọn clip ở tốc độ gốc. Đánh dấu thời điểm đẩy, đặt chân, dừng và chuyển động áo. Nếu thử slow motion, ghi rõ “phát ở 70% tốc độ thực” thay vì “30% slow motion” dễ hiểu nhầm. So sánh lực đẩy, tiếp xúc và nhịp thở; đừng dùng con số trong prompt để khẳng định video đúng vật lý.', 'Watch the whole clip at native speed. Mark push, foot placement, stop and jacket movement. For a slow-motion test, specify “play at 70% of real-time speed” rather than the ambiguous “30% slow motion.” Compare force, contact and breathing; prompt numbers do not certify physical accuracy.'], t('Trình phát video', 'Video player'), 'L08-timing-review.txt'),
        step(['5 · Nộp đúng bài tập L8', '5 · Submit the L8 assignment'], ["Nộp prompt, video và 5-7 câu giải thích vì sao bạn chọn tốc độ và camera đó, cùng điều hành vi cơ thể cho người xem biết. Dựa vào chi tiết nhìn thấy được, thay vì chỉ ghi “căng thẳng” hoặc “hào hứng”.", "Submit the prompt, video and 5-7 sentences explaining the chosen speed and camera, and what the physical behavior tells the viewer. Point to visible details instead of simply writing “tense” or “excited.”"], notes, 'L08-video.mp4 + rationale.txt'),
      ],
      checks: [t('Prompt có đủ lực, trình tự, camera và phản ứng.', 'The prompt includes force, sequence, camera and reaction.'), t('Đã xem chuyển động chính, phụ và điểm tiếp xúc.', 'Main motion, secondary motion and contact have been inspected.'), t("Có video, prompt, thiết lập và giải thích 5-7 câu.", "Video, prompt, settings and a 5-7 sentence rationale are saved.")],
      troubleshooting: [{ problem: t('Các hành động xảy ra cùng lúc hoặc mất trọng lượng.', 'Actions happen simultaneously or look weightless.'), fix: t('Giảm số sự kiện; nêu rõ hành động khởi phát, phản ứng tiếp theo và thời điểm ổn định. Giữ camera đơn giản rồi thử lại.', 'Reduce events; state the initiating action, following response and settling moment. Simplify the camera and retry.') }],
      example: source(1, ['Video 13:51 minh họa mười tình huống và kết thúc bằng bài tập prompt + video + giải thích. “Seedance hiểu vật lý” là cách diễn đạt của giảng viên, không bảo đảm mô phỏng vật lý hay đúng mọi mốc thời gian.', 'The 13:51 recording covers ten situations and ends with prompt, video and rationale. The instructor’s “physics” framing is a directing method, not a guarantee of physical simulation or exact timing.']),
    },
    {
      id: 'planning', goal: t('Phân biệt máy di chuyển, thay đổi tiêu cự và chuyển nét, rồi tạo ba video có thể so sánh.', 'Distinguish camera movement, focal-length changes and focus shifts, then create three comparable test videos.'),
      terms: t('Dolly: máy tiến/lùi trong không gian, làm thay đổi phối cảnh và thị sai. Zoom: thay tiêu cự khi vị trí máy giữ nguyên. Dolly zoom: phối hợp hai thao tác ngược chiều để giữ kích thước chủ thể. Pan/tilt: xoay máy ngang/dọc. Truck/pedestal: tịnh tiến máy ngang/dọc. Rack focus: chuyển mặt phẳng nét. Dutch angle: góc máy nghiêng, không nhất thiết là chuyển động.', 'Dolly translates the camera through space, changing perspective and parallax. Zoom changes focal length from a fixed position. Dolly zoom combines opposing dolly and zoom to retain subject size. Pan/tilt rotate horizontally/vertically; truck/pedestal translate horizontally/vertically. Rack focus shifts the focus plane. Dutch angle is a tilted framing, not necessarily movement.'),
      input: t('Bài nguồn giữ cùng cảnh bộ xương trong phòng khách sạn để so sánh. Bài thực hành này dùng An đứng yên, lan can ở tiền cảnh và biển ở hậu cảnh; hãy dùng cùng một ảnh cho mọi lần thử.', 'The source compares a skeleton in a hotel suite. This exercise uses a stationary An, a foreground railing and the sea behind; use the same image for every test.'),
      steps: [
        step(['1 · Tạo frame có ba lớp chiều sâu', '1 · Create a three-layer reference frame'], ['Dùng ảnh nhân vật đã chốt. Đặt vật gần máy, chủ thể và nền xa để thấy thị sai; tránh nền phẳng. Chỉ tạo một ảnh chuẩn và giữ nguyên cho ba lượt thử.', 'Use the approved character reference. Include a near-camera object, subject and distant background so parallax is visible. Create one baseline image and reuse it for all three tests.'], 'Freepik · Image Generator', 'L09-reference.png', [
          'Dùng ảnh An đã tải lên, giữ mặt và trang phục. Khung ngang 16:9: lan can trắng ở tiền cảnh bên trái, An đứng yên cạnh ván ở trung cảnh, biển và đường chân trời ở hậu cảnh. Máy ngang tầm mắt, thấy đủ người. Nắng cuối chiều từ trái. Có khoảng cách rõ giữa ba lớp, không chữ.',
          'Use the uploaded An reference, preserving face and clothing. Horizontal 16:9: a white railing in the left foreground, An standing beside the board in the middle ground, and sea and horizon far behind. Eye-level camera, full figure visible. Late-afternoon light from the left. Clearly separate the three depth layers; no text.',
        ], 'image'),
        step(['2 · Học 25 kỹ thuật theo thứ tự nguồn', '2 · Study the 25 techniques in source order'], ['Mở thư viện kỹ thuật bên dưới. Trước khi chọn prompt, xác định máy đang tịnh tiến, xoay, đổi tiêu cự hay đổi điểm nét. Giữ chủ thể đứng yên để bạn chỉ quan sát chuyển động của máy.', 'Open the technique library below. Before choosing a prompt, identify whether the camera translates, rotates, changes focal length or shifts focus. Keep the subject still so you can isolate camera behavior.'], 'Freepik · Kling', 'L09-technique-notes.txt'),
        step(['3 · Tạo ba video kiểm chứng', '3 · Generate three comparison videos'], ['Chọn ba kỹ thuật khác nhau trong thư viện; nên thử dolly in, zoom in và rack focus trước. Dùng cùng ảnh, thời lượng và model nếu giao diện cho phép. Mỗi lượt chỉ đổi chỉ dẫn camera; ghi lại mọi thiết lập khác buộc phải thay.', 'Choose three different library techniques; dolly in, zoom in and rack focus make a useful first comparison. Keep the image, duration and model unchanged where the interface permits. Change only the camera instruction and log any unavoidable setting changes.'], 'Freepik · Kling', 'L09-camera-01.mp4 … 03.mp4 + prompts + settings'),
        step(['4 · So sánh và giải thích', '4 · Compare and explain'], ['Xem ba clip cạnh nhau hoặc nối tiếp. Dolly phải làm thay đổi quan hệ giữa tiền cảnh và hậu cảnh; zoom không nên tự tạo đường đi của máy; rack focus đổi vùng nét, không đổi cỡ cảnh. Nộp ba video, prompt và lý do dùng từng kỹ thuật trong câu chuyện. Nếu kết quả sai, ghi lỗi rồi thử lại; đừng đổi tên kỹ thuật để khớp với kết quả.', 'Watch the three clips together or in sequence. A dolly should change the relationship between foreground and background; a zoom should not create camera travel; rack focus changes sharpness, not shot size. Submit all three videos, prompts and a narrative reason for each technique. If a result is wrong, log the problem and retry; do not rename the technique to fit the result.'], notes, 'L09-comparison.txt'),
      ],
      techniques: cinemaCameraLabs(locale),
      checks: [t('Có ba video, cùng ảnh gốc và thiết lập được ghi lại.', 'Three videos share a reference and have recorded settings.'), t('Đánh giá chuyển động thực tế, không chỉ tên preset.', 'Actual behavior is checked, not just preset names.'), t('Giải thích được dolly, zoom, rack focus và góc nghiêng.', 'Dolly, zoom, rack focus and Dutch angle are distinguished.')],
      troubleshooting: [{ problem: t('Zoom trông giống dolly hoặc chủ thể tự di chuyển.', 'The zoom behaves like a dolly or the subject moves.'), fix: t('Nhắc rõ máy cố định và chủ thể đứng yên; dùng ảnh có ba lớp chiều sâu. Nếu model vẫn trộn hành vi, ghi nhận giới hạn và thử lại từng kỹ thuật.', 'Specify a fixed camera and stationary subject; use three visible depth layers. If the model still mixes behaviors, record that limitation and retry one technique at a time.') }],
      example: source(2, ['Video 13:42 trình diễn 25 kỹ thuật với cùng một cảnh. Các prompt dưới đây là bài tập mới giữ phương pháp so sánh đó; không phải bản sao hay bằng chứng Kling luôn tuân thủ camera.', 'The 13:42 recording demonstrates 25 techniques with one scene. These original prompts preserve that comparison method; they are not copied outputs or evidence of guaranteed camera control.']),
    },
    {
      id: 'frames', goal: t('Làm việc trong Luma theo một chuỗi rõ ràng: bộ góc nhìn nhân vật, frame điện ảnh, rồi chuyển động và các lần sửa có kiểm soát.', 'Work through Luma in a clear sequence: character views, a cinematic still, then animation and controlled refinements.'),
      terms: t('Character turnaround: bộ hình nhân vật nhìn từ trước, bên và sau. Reference selection: chọn đúng ảnh tham chiếu trong cuộc hội thoại. Iteration: sửa từng điểm và so sánh với phiên bản trước; ngữ cảnh hội thoại không bảo đảm giữ nhận diện.', 'A character turnaround shows front, side and back views. Reference selection identifies the image used by a conversation step. Iteration changes one issue and compares versions; conversational context does not guarantee identity preservation.'),
      input: t('Ảnh nhân vật An và một ý tưởng hành động đơn giản. Bài nguồn mang tên “Luma and Runway Integration”, nhưng video 7:15 thực tế dùng Luma Uni-1 và so sánh Kling với Ray 3.14; không có hướng dẫn thao tác Runway.', 'An’s reference and one simple action. The source title is “Luma and Runway Integration,” but the 7:15 recording demonstrates Luma Uni-1 and compares Kling with Ray 3.14; it contains no Runway walkthrough.'),
      steps: [
        step(['1 · Tạo đủ bộ góc nhìn', '1 · Complete the character turnaround'], ['Mở một dự án/cuộc hội thoại trong Luma, tải ảnh nhân vật và yêu cầu ba góc. Nếu chỉ nhận mặt trước, chọn ảnh đó rồi yêu cầu riêng mặt bên và sau. Kiểm tra mặt, mũ, màu áo và tỷ lệ trước bước tiếp.', 'Open a Luma project/conversation, upload the character and request three views. If only a front view appears, select it and request side and back views separately. Check face, helmet, clothing colors and proportions before continuing.'], 'Luma', 'L10-front.png + side.png + back.png', [
          'Từ ảnh nhân vật đã chọn, tạo bộ góc nhìn toàn thân: trước, bên trái và sau. Cùng An, mũ ngọc lam, áo khoác kem, quần xám than, giày trắng; không thiết kế lại. Nền xám, ánh sáng mềm, tư thế trung tính. Nếu chỉ tạo một góc mỗi lượt, tạo góc trước trước; tôi sẽ chọn ảnh rồi yêu cầu góc bên và sau.',
          'From the selected character reference, create full-body front, left-side and back views. Keep the same An, teal helmet, cream jacket, charcoal trousers and white shoes; do not redesign. Gray background, soft light, neutral pose. If only one view is possible per request, generate the front first; I will select it and request side and back views next.',
        ], 'image'),
        step(['2 · Chọn ảnh và dựng frame', '2 · Select references and build the still'], ['Trong giao diện của video, bấm để chọn ảnh; giữ Shift để chọn nhiều ảnh. Kiểm tra ảnh thực sự được đính kèm trong giao diện hiện tại, không chỉ nhắc tên bằng chữ. Tạo một frame An chuẩn bị đẩy ván.', 'In the recorded interface, click to select an image and hold Shift for multiple images. Check that the current interface actually attaches the references rather than merely mentioning their names. Create a still of An preparing to push.'], 'Luma', 'L10-cinematic-still.png', [
          'Dùng các góc nhìn nhân vật đã chọn làm tham chiếu. An chuẩn bị đẩy ván trên đường ven biển, chân trước trên ván, chân sau chạm đất. Toàn vừa ngang tầm hông, thấy hai chân và toàn bộ ván. Nắng cuối chiều từ trái, biển bên phải. Giữ nhận diện và trang phục; một frame điện ảnh, không bảng ghép.',
          'Use the selected character views as references. An prepares to push along a coastal road, front foot on the board and rear foot on the ground. Hip-height medium-wide framing, both feet and the whole board visible. Late-afternoon light from the left, sea on the right. Preserve identity and clothes; one cinematic still, not a grid.',
        ], 'image'),
        step(['3 · Sửa một chi tiết trong frame', '3 · Refine one detail in the still'], ['Chọn chính ảnh vừa tạo, chỉ yêu cầu sửa một điểm và giữ phần còn lại. Ví dụ dưới đây sửa vị trí chân; chỉ dùng khi ảnh có lỗi đó. Lưu trước/sau để xem lần sửa có làm nhận diện thay đổi không.', 'Select the generated still, request only one change and preserve the rest. The example fixes foot placement; use it only when that defect is present. Save before/after versions to see whether the edit changed the identity.'], 'Luma', 'L10-still-before.png + after.png', [
          'Chỉ sửa chân trước của An để đế giày nằm hoàn toàn trên mặt ván, bàn chân và ván có tỷ lệ tự nhiên. Giữ nguyên khuôn mặt, quần áo, vị trí máy, bố cục, nền và ánh sáng của ảnh đã chọn.',
          'Only fix An’s front foot so the sole rests fully on the deck with natural foot-to-board proportions. Preserve the selected image’s face, clothing, camera position, composition, background and light.',
        ], 'image'),
        step(['4 · Animate rồi so sánh', '4 · Animate and compare'], ['Chọn frame đã duyệt, tạo chuyển động đơn giản. Video nguồn so sánh Kling và Ray 3.14 trong cùng quy trình; dùng đúng model khả dụng và ghi tên/phiên bản thực tế. Nếu so sánh hai model, giữ ảnh và yêu cầu hành động giống nhau. Sửa tiếp xúc, trọng lượng hoặc nhịp chuyển động từng điểm.', 'Select the approved still and animate a simple action. The recording compares Kling and Ray 3.14 within the workflow; record the actual available model and version. For a two-model comparison, retain the same image and action request. Refine contact, weight or timing one issue at a time.'], 'Luma · video model', 'L10-animation.mp4 + model-settings.txt', [
          'Animate ảnh đã chọn thành một shot liên tục: An dùng chân sau đẩy một lần, đưa chân đó lên ván rồi trượt êm. Gối hơi chùng để giữ cân bằng; vạt áo phản ứng chậm hơn thân người. Máy theo ngang êm, thấy đủ ván và hai chân. Giữ nhân vật, bố cục, hướng nắng và đường ven biển. Không thêm cú nhảy hoặc cắt cảnh.',
          'Animate the selected still as one continuous shot: An pushes once with the rear foot, places it on the board and rolls smoothly. Knees stay slightly bent for balance; the jacket follows body movement with a delay. Smooth lateral camera follow, keeping board and feet visible. Preserve character, composition, sunlight direction and coast. Add no jump or cut.',
        ], 'video'),
        step(['5 · Nộp bộ ba đầu ra', '5 · Submit all three outputs'], ['Nộp bộ góc nhìn nhân vật, frame điện ảnh và video, kèm prompt, model và một ghi chú chỉnh sửa trước/sau. Các ảnh trong cùng một cuộc hội thoại vẫn cần được chọn và kiểm tra như reference.', 'Submit the character turnaround, cinematic still and animation with prompts, model settings and one before/after refinement note. Images in the same conversation still need to be selected and checked as references.'], notes, 'L10-delivery/'),
      ],
      checks: [t('Có đủ góc trước, bên, sau.', 'Front, side and back views are complete.'), t('Reference được chọn thật; frame và video giữ nhận diện.', 'References are actually attached; still and animation retain identity.'), t('Đủ ba loại đầu ra và ghi chú phiên bản.', 'All three output types and version notes are saved.')],
      troubleshooting: [{ problem: t('Luma chỉ tạo một góc hoặc quên chi tiết.', 'Luma returns one view or loses details.'), fix: t('Chọn ảnh chuẩn, yêu cầu riêng góc còn thiếu và nêu những đặc điểm cần giữ. Giảm phạm vi chỉnh sửa rồi đối chiếu lại.', 'Select the approved reference, request the missing view separately and name the features to preserve. Narrow the edit and compare again.') }],
      example: source(3, ['Nguồn dùng nhân vật cao bồi và ngựa để minh họa chuỗi hội thoại, chọn ảnh và sửa chuyển động. Workshop giữ đúng ba giai đoạn, dùng cảnh An riêng; không bổ sung một quy trình Runway chưa được video trình diễn.', 'The source uses a cowboy and horse to demonstrate conversation, reference selection and motion refinement. This workshop retains the three stages with an original An scene; it does not invent a Runway workflow.']),
    },
    {
      id: 'motion', goal: t('Hiểu mỗi điểm cắt làm gì, rồi tạo ba chuỗi: jump cut, match cut và cut on action.', 'Understand what each edit does, then create three sequences: jump cut, match cut and cut on action.'),
      terms: t('Jump cut: lược thời gian trong khung hình tương tự. Match cut: nối tương đồng hình dáng/bố cục. Cut on action: nối cùng một động tác đang diễn ra qua góc khác. Cross-cutting: đan xen sự kiện diễn ra đồng thời. Double cut: lặp lại khoảnh khắc hành động từ góc khác để nhấn mạnh. Fast cutting: chuỗi shot ngắn tạo nhịp.', 'Jump cut removes time within similar framing. Match cut connects graphic shapes or composition. Cut on action continues the same ongoing movement across angles. Cross-cutting alternates simultaneous events. Double cut repeats an action moment from another angle for emphasis. Fast cutting uses brief shots to build rhythm.'),
      input: t('Bài nguồn có tiêu đề “Camera Movement”, nhưng video 4:46 dạy sáu kỹ thuật cắt dựng bằng Seedance trong CapCut. Lời kết nói “năm”, còn phần trình diễn thực tế có sáu kỹ thuật.', 'The source is titled “Camera Movement,” but the 4:46 recording teaches six editing techniques with Seedance in CapCut. Its closing narration says “five,” while six techniques are demonstrated.'),
      steps: [
        step(['1 · Xác định thứ được giữ và thứ thay đổi', '1 · Identify what stays and what changes'], ['Xem sáu kỹ thuật theo thứ tự: jump, match, cut on action, cross-cutting, double cut, fast cutting. Ở mỗi điểm cắt, ghi thời gian, góc máy, chủ thể, hình dáng hay động tác đã thay đổi. Double cut cố ý lặp một khoảnh khắc; cut on action tiếp tục hành động qua điểm cắt.', 'Study the six techniques in order: jump, match, cut on action, cross-cutting, double cut, fast cutting. At each edit, record whether time, angle, subject, shape or movement changes. Double cut intentionally repeats a moment; cut on action continues an action through the edit.'], notes, 'L11-cut-analysis.txt'),
        step(['2 · Tạo jump cut', '2 · Create a jump cut'], ['Giữ máy và bố cục, lược những khoảng chờ. Xem kết quả có cắt thời gian thật hay chỉ tua nhanh; ghi những frame trước/sau điểm cắt.', 'Keep camera and composition, removing waiting time. Check for actual time omissions rather than a speed-up; note frames immediately around each cut.'], 'CapCut · Seedance', 'L11-jump-cut.mp4 + prompt.txt', [
          'Một chuỗi ba shot ngắn cùng máy cố định và cùng bố cục: An đứng cạnh ván ở trung cảnh. Shot 1 An cài quai mũ; jump cut bỏ thời gian chờ sang shot 2 An đã cúi xuống kiểm tra bánh; jump cut sang shot 3 An đã đứng lại, tay cầm ván. Cùng địa điểm, ánh sáng, trang phục và tỷ lệ. Điểm cắt dứt khoát, không dissolve, không tua nhanh, không morph giữa tư thế.',
          'A sequence of three brief shots with the same locked camera and composition: An stands beside the board in a medium view. Shot 1: An fastens the helmet strap; jump cut over waiting time to shot 2 with An already bent over checking a wheel; jump cut to shot 3 with An standing again, holding the board. Same location, light, clothing and scale. Clean cuts, no dissolve, speed-up or morph between poses.',
        ], 'video'),
        step(['3 · Tạo match cut theo hình dáng', '3 · Create a graphic match cut'], ['Chọn hai hình có hình dáng và vị trí giống nhau. Bài tập này nối bánh ván với chiếc đồng hồ; đây là tương đồng thị giác, không phải nối một động tác liên tục.', 'Choose two shapes aligned in size and position. This exercise connects a skateboard wheel to a clock through visual similarity, not continuous action.'], 'CapCut · Seedance', 'L11-match-cut.mp4 + prompt.txt', [
          'Hai shot nối bằng một graphic match cut. Shot A: cận một bánh ván tròn màu đen ở chính giữa khung hình. Cắt thẳng sang shot B: đồng hồ tròn treo trên tường, mặt đồng hồ có cùng kích thước và tâm trong khung hình với bánh xe. Giữ đường tròn khớp tại điểm cắt. Hai vật và hai không gian khác nhau; không biến hình bánh xe thành đồng hồ, không dissolve.',
          'Two shots connected by a graphic match cut. Shot A: a close-up of a black circular skateboard wheel centered in frame. Cut directly to shot B: a circular wall clock with the same on-screen diameter and center as the wheel. Align the circles across the edit. These are different objects and spaces; do not morph the wheel into a clock or dissolve between them.',
        ], 'video'),
        step(['4 · Tạo cut on action', '4 · Create a cut on action'], ["Chọn một động tác có đầu-giữa-cuối rõ. Cắt giữa động tác và tiếp tục đúng giai đoạn ở góc mới. Kiểm tra tay/chân không đổi vị trí đột ngột, không lặp hoặc bỏ mất hành động.", 'Choose an action with a clear beginning, middle and end. Cut mid-action and continue from the same phase in the new angle. Check for limb discontinuities, repeated movement or missing action.'], 'CapCut · Seedance', 'L11-cut-on-action.mp4 + prompt.txt', [
          'Hai shot của cùng một động tác An nhấc ván khỏi mặt đất. Shot A trung cảnh: An cúi người, tay phải nắm đầu ván rồi bắt đầu nhấc. Cắt khi ván vừa rời đất sang shot B cận tay phải và ván từ góc bên; tiếp tục cùng chuyển động nâng, không bắt đầu lại. Giữ hướng nâng, tay nắm, vị trí ván và ánh sáng qua điểm cắt. Không dissolve, không thêm tay hay ván khác.',
          'Two shots of the same action as An lifts the board from the ground. Shot A, medium: An bends, grips the nose with the right hand and begins lifting. Cut as the board leaves the ground to shot B, a side close-up of that hand and board; continue the same upward movement without restarting. Preserve lift direction, grip, board placement and light across the cut. No dissolve or additional hand or board.',
        ], 'video'),
        step(['5 · Kiểm tra bài nộp', '5 · Review the submission'], ["Nộp ba chuỗi cùng prompt. Mỗi chuỗi viết 1-2 câu: điều gì được giữ, điều gì thay đổi, vì sao điểm cắt có tác dụng. Nếu AI tạo morph hoặc sai nhịp, tạo lại từng shot và nối trong timeline; ghi rõ phần nào do AI tạo, phần nào tự dựng.", "Submit the three sequences and prompts. Write 1-2 sentences each: what remains, what changes and why the edit works. If AI produces a morph or mistimed cut, regenerate separate shots and assemble them in an editing timeline; record what was generated and what was edited manually."], 'CapCut + ' + notes, 'L11-three-sequences/ + review.txt'),
      ],
      checks: [t('Ba chuỗi thể hiện đúng ba kỹ thuật được giao.', 'The three assigned techniques are visibly distinct.'), t('Không nhầm graphic match với match on action.', 'Graphic matching is distinguished from matching action.'), t("Mỗi chuỗi có 1-2 câu giải thích và prompt.", "Each sequence has a prompt and a 1-2 sentence explanation.")],
      troubleshooting: [{ problem: t('Model dùng morph thay cho điểm cắt.', 'The model morphs instead of cutting.'), fix: t('Tạo hai shot riêng và cắt trực tiếp trong timeline. So sánh frame cuối và đầu; không gọi morph là match cut.', 'Generate separate shots and place a direct cut in the timeline. Compare outgoing and incoming frames; do not label a morph a match cut.') }],
      example: source(4, ['Sáu kỹ thuật là nội dung học; bài tập cuối chỉ yêu cầu ba chuỗi jump cut, match cut và cut on action. Các ví dụ An ở đây được biên soạn riêng và chưa tạo video.', 'All six techniques belong to the lesson; the final assignment requests only jump cut, match cut and cut-on-action sequences. The An examples are original, ungenerated practice prompts.']),
    },
    {
      id: 'review', goal: t('Chọn cỡ cảnh phù hợp thông tin và cảm xúc, rồi viết một prompt video 5 giây có hai khối thời gian.', 'Choose framing that suits the information and emotion, then write one five-second video prompt with two time blocks.'),
      terms: t('Establishing shot: cảnh giới thiệu không gian, là chức năng kể chuyện. Wide/full shot: toàn cảnh/toàn thân để đọc người trong không gian. Medium wide/cowboy: toàn vừa, thường từ đùi hoặc gần đầu gối lên. Medium: trung cảnh, khoảng thắt lưng lên. Medium close-up: trung cận, khoảng ngực lên. Close-up: cận cảnh mặt. Extreme close-up: đặc tả một chi tiết. Ranh giới cỡ cảnh có thể thay đổi theo bố cục.', 'An establishing shot introduces a place; it describes a narrative function. Wide/full shots show the figure in its surroundings. Medium-wide/cowboy framing generally begins around the thighs or knees. Medium is roughly waist-up; medium close-up roughly chest-up; close-up emphasizes the face; extreme close-up isolates a detail. These boundaries vary with composition.'),
      input: t('Video 16:13 đi từ không gian rộng đến chi tiết qua cảnh sa mạc, tàu vũ trụ, nhân vật và phản chiếu trong mắt. Dùng frame An để thực hành cùng nguyên tắc, không cần sao chép nhân vật nguồn.', 'The 16:13 recording moves from large spaces to details through desert, spacecraft, character and eye-reflection examples. Use An’s reference to practice the same principle without copying the source character.'),
      steps: [
        step(['1 · So sánh bảy cách đóng khung', '1 · Compare seven framing choices'], ['Theo thứ tự nguồn: establishing → wide/full → medium wide/cowboy → medium → medium close-up → close-up → extreme close-up. Với mỗi loại, ghi người xem biết thêm điều gì và mất bớt điều gì. Chuỗi rộng đến gần là bài tập quan sát, không phải luật mọi cảnh phải tuân theo.', 'Follow the source order: establishing → wide/full → medium-wide/cowboy → medium → medium close-up → close-up → extreme close-up. For each, note what viewers learn and what context disappears. Wide-to-close is an observation exercise, not a mandatory order for every scene.'], notes, 'L12-framing-notes.txt'),
        step(['2 · Chọn một cỡ cảnh và giải thích', '2 · Select one framing and explain'], ["Chọn đúng một cỡ cảnh cho clip 5 giây. Viết 3-5 câu giải thích vì sao nó phù hợp câu chuyện và cảm xúc. Xác định môi trường, ánh sáng, nhân vật và hai khối thời gian; âm thanh có thể ảnh hưởng cách cảm nhận nhưng bài tập nguồn yêu cầu không có âm thanh.", "Choose one framing for a five-second clip. Write 3-5 sentences explaining its narrative and emotional purpose. Define environment, light, character and two time blocks. Sound can affect perception, but this source assignment explicitly requires no audio."], notes, 'L12-rationale.txt'),
        step(['3 · Viết prompt 5 giây', '3 · Write the five-second prompt'], ['Ví dụ chọn trung cận để đọc hơi thở và ánh mắt trước khi An bắt đầu trượt. “Practical-effects look” mô tả thẩm mỹ; video AI không trở thành cảnh quay thật vì có câu “no CGI”. Nếu nêu tiêu cự, coi đó là ý đồ hình ảnh và kiểm tra kết quả, không coi là mô phỏng quang học chính xác.', 'The example chooses medium close-up to read breath and eyes before An starts riding. “Practical-effects look” describes an aesthetic; saying “no CGI” does not make AI video real footage. Treat any stated focal length as visual intent and inspect the result rather than assuming exact optical simulation.'], 'CapCut · Seedance', 'L12-five-second-prompt.txt', [
          'Định dạng: video 5 giây, khung ngang 16:9, không có âm thanh.\nCỡ cảnh: trung cận, từ ngực lên; máy cố định ngang mắt.\nMôi trường: đường ven biển, nền biển dịu và không lấn át mặt.\nÁnh sáng: nắng tự nhiên cuối chiều từ trái, màu da tự nhiên.\nNhân vật: An theo ảnh đã tải lên, mũ ngọc lam và áo khoác kem, giữ nhận diện.\n0–2 giây: An nhìn về đoạn đường phía trước, hít vào nhẹ, vai nâng rất ít.\n2–5 giây: An thở ra, mắt tập trung hơn, cằm hạ nhẹ; khung hình giữ nguyên, không cắt.\nThẩm mỹ: chất liệu tự nhiên như phim dùng hiệu ứng thực tế, không bóng nhựa hoặc hiệu ứng số phô trương. Không nhạc, lời nói hay hiệu ứng âm thanh.',
          'Format: five-second horizontal 16:9 video, no audio.\nShot: medium close-up, chest-up; locked eye-level camera.\nEnvironment: a coastal road with a soft sea background that does not overpower the face.\nLight: natural late-afternoon sunlight from the left, natural skin tones.\nCharacter: An from the uploaded reference, teal helmet and cream jacket; preserve identity.\n0–2 seconds: An looks along the road and inhales gently, with a slight shoulder rise.\n2–5 seconds: An exhales, eyes focus and chin lowers slightly; maintain framing, no cut.\nAesthetic: natural textures and a practical-effects film look, without plastic skin or conspicuous digital effects. No music, dialogue or sound effects.',
        ], 'video'),
        step(['4 · Kiểm tra hoặc mô tả kết quả dự kiến', '4 · Inspect or describe the expected result'], ["Bài nguồn cho phép tạo video hoặc mô tả kết quả dự kiến. Nếu tạo, kiểm tra đủ 5 giây, đúng cỡ cảnh, hai nhịp hành động và không có âm thanh. Nếu chưa tạo, ghi rõ “dự kiến”, mô tả cụ thể hai mốc và không trình bày như kết quả đã kiểm chứng. Nộp prompt cùng giải thích 3-5 câu.", "The source permits either generation or an expected-result description. If generated, check five-second duration, framing, two action beats and no audio. Otherwise label the description “expected,” describe both intervals concretely and do not present it as a tested result. Submit the prompt with the 3-5 sentence rationale."], notes, 'L12-video.mp4 OR expected-result.txt + rationale.txt'),
      ],
      checks: [t('Một cỡ cảnh có lý do kể chuyện rõ.', 'One framing choice has a clear narrative purpose.'), t("Prompt đủ trường, hai khối thời gian phủ 0-5 giây và không âm thanh.", "Required fields and two time blocks cover 0-5 seconds with no audio."), t("Có 3-5 câu giải thích; phân biệt video thật và mô tả dự kiến.", "A 3-5 sentence rationale distinguishes generated video from expected results.")],
      troubleshooting: [{ problem: t('Camera tiến vào hoặc video tự thêm nhạc.', 'The camera pushes in or music is added.'), fix: t('Nhắc máy cố định và tắt audio trong thiết lập nếu có. Kiểm tra file; khi cần, bỏ track âm thanh trong trình dựng rồi ghi lại thao tác.', 'Specify a locked camera and disable audio in available settings. Inspect the file; if necessary, remove the audio track in an editor and record that operation.') }],
      example: source(5, ["Phần giảng bàn cả âm thanh; yêu cầu bài tập cuối vẫn là clip 5 giây không âm thanh với hai khối thời gian và giải thích 3-5 câu. Workshop giữ nguyên yêu cầu cuối đó.", "The teaching discusses sound, but the final assignment is a silent five-second clip with two time blocks and a 3-5 sentence rationale. This workshop preserves that assignment."]),
    },
    {
      id: 'delivery', goal: t('Chuyển storyboard sáu shot thành video 15 giây bằng YAML có cấu trúc, giữ nhận diện và dùng ít nhất ba kiểu chuyển cảnh.', 'Translate a six-shot storyboard into a 15-second video using structured YAML, consistent identity and at least three transition types.'),
      terms: t('YAML tổ chức nội dung bằng key: value và thụt lề bằng dấu cách. character_modeling mô tả nhận diện; cinematic_storyboard chia shot; production_notes ghi ràng buộc chung. Đây là cách viết prompt trong Loom, không phải schema API chính thức hay bảo đảm Seedance thực thi mọi trường. Match on action nối cùng động tác; chỉ đi theo ánh mắt chưa đủ tạo kiểu nối này.', 'YAML organizes key: value pairs through space indentation. character_modeling describes identity; cinematic_storyboard separates shots; production_notes holds global constraints. This is the Loom’s prompting structure, not an official API schema or guaranteed Seedance behavior. Match on action continues the same movement; following an eyeline alone does not establish it.'),
      input: t('Loom 6:17 của Darren Maen dùng nhân vật mèo hồng trên ván. Bài thực hành giữ phương pháp, thứ tự và mốc thời gian nhưng dùng nhân vật An riêng. L7 đã dạy dựng cảnh; ở đây dựng storyboard mới cho đoạn đang trượt, không tái dùng sáu shot lấy ván khác nội dung.', 'Darren Maen’s 6:17 Loom uses a pink cat rider. This original An exercise preserves the method, shot order and timing. L7 taught scene construction; now make a new storyboard for the ride instead of reusing the different board-pickup sequence.'),
      steps: [
        step(['1 · Tạo storyboard sáu shot cho đoạn chuyển động', '1 · Create the six-shot motion storyboard'], ['Giữ silhouette, chất liệu, tỷ lệ và trang phục nhân vật. Theo Loom: drone nhìn xuống → wide đang trượt → medium vào cua → close-up mặt → ván/động tác nhảy → wide kết. Tạo một tờ kết hợp nhân vật và phân cảnh, kiểm tra cả sáu ô trước khi tải lên.', 'Preserve silhouette, materials, proportions and clothes. Follow the Loom: top-down drone → wide riding → medium turning → facial close-up → board/jump action → final wide. Create one combined character-and-storyboard sheet and inspect all six panels before uploading.'], 'Freepik · Assistant', 'L13-storyboard.png', [
          'Dùng reference An đã duyệt: mũ ngọc lam, áo khoác kem, quần xám than, giày trắng, ván gỗ bánh đen. Tạo một storyboard điện ảnh 3 cột × 2 hàng, sáu ô theo thứ tự, mỗi ô khung ngang 16:9. 1 drone nhìn thẳng xuống đường ven biển; 2 wide An đang trượt; 3 medium An nghiêng người vào cua; 4 cận mặt An nhìn đường; 5 góc thấp ván và hai chân trong một cú bật nhỏ qua gờ; 6 wide từ sau An đi xa. Cùng con đường, lan can trắng, biển bên phải và nắng cuối chiều từ trái; giữ thiết kế nhân vật và hướng di chuyển trong không gian. Không chữ, không thêm ô.',
          'Use the approved An reference: teal helmet, cream jacket, charcoal trousers, white shoes, wood board with black wheels. Create one cinematic storyboard, three columns by two rows, six ordered panels with 16:9 framing inside each. 1 top-down drone over the coastal road; 2 wide of An riding; 3 medium of An leaning into a turn; 4 facial close-up looking along the road; 5 low view of board and feet during one small hop over a seam; 6 rear wide as An recedes. Same road, white railing, sea to the right and late-afternoon light from the left; preserve design and geographic travel direction. No text or extra panels.',
        ], 'image'),
        step(['2 · Tải ảnh và khóa nhận diện', '2 · Upload the sheet and define identity'], ['Trong Seedance, tải storyboard thật lên làm reference. Chọn nó qua bộ chọn tham chiếu để liên kết @image1; gõ tên mà không đính kèm ảnh là chưa đủ. Kiểm tra thứ tự ảnh nếu dùng nhiều reference. Trong character_modeling, mô tả những chi tiết cần giữ, không đưa camera hoặc hành động vào khối này.', 'Upload the actual storyboard to Seedance as a reference. Attach it through the reference picker so @image1 points to that sheet; typing the name alone is insufficient. Check image ordering if using multiple references. Keep identity constraints in character_modeling, separate from camera and action.'], 'Seedance 2 · reference', 'L13-reference-check.txt'),
        { ...step(['3 · Sao chép YAML và kiểm tra cấu trúc', '3 · Copy YAML and inspect its structure'], ["Sao chép toàn bộ khối bằng nút Copy. Giữ dấu cách đầu dòng, không dùng tab. Các key giữ bằng tiếng Anh ở cả hai bản; phần mô tả được dịch. Mỗi camera chỉ có vị trí/cỡ cảnh, một chuyển động chính và cách vận hành; không thêm danh sách thông số ống kính/FPS vào bài này. Các trường action, lighting, sfx (âm thanh) và transition có vai trò riêng. Timeline liên tục: 0-2, 2-4, 4-6, 6-8, 8-12, 12-15 giây.", "Use Copy for the entire block. Preserve leading spaces; do not use tabs. Keys stay in English in both versions while values are translated. Each camera field specifies position/framing, one main movement and behavior; do not add lens/FPS specification lists in this lesson. Keep action, lighting, sfx (sound) and transition separate. The continuous timeline is 0-2, 2-4, 4-6, 6-8, 8-12 and 12-15 seconds."], 'Seedance 2 · YAML prompt', 'L13-prompt.yaml', [cinemaYaml('vi'), cinemaYaml('en')], 'video'), promptFormat: 'yaml' },
        step(['4 · Đọc các điểm chuyển trước khi chạy', '4 · Read transitions before generating'], ['2s: cut giữ hướng đi; 4s: whip pan ngang dùng nhòe chuyển động; 6s: smash cut đổi nhịp sang cận mặt; từ 7.6s: hướng nhìn hạ xuống và bắt đầu hạ trọng tâm, nối hành động đó vào shot ván tại 8s; 12s: whip hướng lên mở wide; giữ đến 15s. Mỗi chuyển cảnh cần dẫn sự chú ý hoặc nhịp cảm xúc của người xem.', 'At 2s, cut while preserving travel direction; at 4s, horizontal whip pan carries motion blur; at 6s, smash cut changes pace into the facial close-up; from 7.6s, follow the eyeline down and begin a crouch, continuing that action into the board shot at 8s; at 12s, whip upward to the wide; hold to 15s. Each transition should guide the viewer’s attention or emotional rhythm.'], notes, 'L13-transition-map.txt'),
        step(['5 · Tạo, xem trọn clip và sửa một lỗi mỗi lượt', '5 · Generate, watch fully and refine one issue'], ['Chọn thời lượng 15 giây và model Seedance 2 theo bài nguồn nếu khả dụng; ghi chính xác phiên bản sử dụng. Dán YAML và chạy. Xem toàn bộ clip, rồi kiểm tra từng ranh giới shot: mặt/mũ/áo, tay chân, ván, hướng đi, ánh sáng, tiếp xúc và transition. YAML hợp lệ không có nghĩa model sẽ làm đúng. Nếu không giữ được sáu shot, thử lại có kiểm soát hoặc tạo từng shot rồi dựng; ghi rõ cách làm thay thế.', 'Choose 15 seconds and the source’s Seedance 2 model where available; log the exact version used. Paste the YAML and generate. Watch the entire clip, then inspect each boundary for face, helmet, clothes, limbs, board, direction, lighting, contact and transition. Valid YAML does not guarantee model compliance. If six shots fail, iterate deliberately or generate shots separately and edit them, documenting the fallback.'], 'Seedance 2 + ' + notes, 'L13-video-v01.mp4 + review.txt'),
        step(['6 · Nộp bài cuối', '6 · Submit the final exercise'], ['Nộp storyboard sáu shot, YAML có character_modeling và cinematic_storyboard, video 15 giây, model/thiết lập và ghi chú review. Video cần thể hiện ít nhất ba kiểu chuyển cảnh rõ ràng. Đối chiếu các mốc mục tiêu với mốc thật, ghi lỗi còn lại và phiên bản sửa; chỉ gọi kết quả đã kiểm chứng sau khi đã xem file.', 'Submit the six-shot storyboard, YAML containing character_modeling and cinematic_storyboard, the 15-second video, model/settings and review notes. The video should visibly demonstrate at least three transition types. Compare target and actual boundaries, record remaining defects and revisions, and call a result verified only after inspecting the file.'], notes, 'L13-final/ · storyboard + YAML + video + review'),
      ],
      checks: [t('Reference thật gắn đúng @image1; sáu shot đúng thứ tự.', 'An actual reference is attached as @image1; six shots are ordered correctly.'), t('YAML sao chép giữ thụt lề; sáu khoảng liên tục phủ 15 giây.', 'Copied YAML retains indentation; six contiguous intervals cover 15 seconds.'), t('Ít nhất ba kiểu chuyển cảnh nhìn thấy được, không chỉ được viết trong prompt.', 'At least three transition types are visible, not merely written in the prompt.'), t('Đã kiểm tra nhận diện, tiếp xúc, camera, ánh sáng và âm thanh.', 'Identity, contact, camera, light and sound have been reviewed.')],
      troubleshooting: [{ problem: t('YAML lỗi hoặc video bỏ shot/chuyển cảnh.', 'YAML is malformed or the video omits shots/transitions.'), fix: t('Kiểm tra thụt lề bằng trình phân tích YAML trước. Nếu cú pháp đúng, giảm mệnh lệnh xung đột, sửa một ranh giới rồi tạo lại. Đừng cho rằng model đã đọc YAML như chương trình.', 'Validate indentation with a YAML parser first. If syntax is correct, reduce conflicting instructions, refine one boundary and regenerate. Do not assume the model executes YAML as a program.') }],
      example: { ...source(6, ['Loom 6:17: 0:20 thiết kế nhân vật; 0:33 thứ tự sáu shot; 0:54 tải storyboard; 1:08 giữ nhận diện; 1:37 cấu trúc YAML; 2:47 camera; 3:12 timeline; 4:00 production_notes; 4:13 chuyển cảnh. Ví dụ An giữ các mốc này và dùng mô tả mới. Xem Loom qua liên kết bên dưới.', 'Loom 6:17: 0:20 character design; 0:33 six-shot order; 0:54 storyboard upload; 1:08 identity; 1:37 YAML structure; 2:47 camera; 3:12 timeline; 4:00 production_notes; 4:13 transitions. The original An example retains this structure and timing. The link below opens the Loom.']), href: 'https://www.loom.com/share/7db77e6fca8c44cb924fb31935770356' },
    },
  ];
  // Beginner handoffs live beside the course so the classroom and workbook agree.
  const add = (lesson: number, stepIndex: number, vi: string, en: string) => {
    lessons[lesson].steps[stepIndex].instruction += ` ${t(vi, en)}`;
  };
  lessons[0].input = t('Đây là bài đầu của workshop này; số L7 chỉ là cách đánh số của tài liệu nguồn. Không cần làm L1-L6. Chuẩn bị công cụ chat, công cụ tạo ảnh và thư mục L07. Nhân vật An và con đường ven biển được tạo ngay trong các bước dưới.', 'This is the first lesson in this workshop; L7 is the source lesson number. You do not need L1-L6. Have a chat tool, an image generator and an L07 folder ready. You will create An and the coastal road in the steps below.');
  add(0, 0, 'Mở cuộc trò chuyện mới, bấm Copy ở prompt dưới rồi dán và gửi. Đọc đủ sáu mục trước khi lưu: mỗi mục phải có một hành động chính. Trong Spaces, dùng nút + để thêm node Text, dán kịch bản và đặt tên script. Nếu chưa dùng Spaces, lưu kịch bản trong file văn bản và đính kèm khi công cụ tạo ảnh hỗ trợ.', 'Open a new chat, click Copy below, paste and send. Check that the response has six numbered shots with one main action each. In Spaces, use + to add a Text node, paste the script and name it script. If you are not using Spaces, save the script as a text file and attach it where your image tool supports attachments.');
  add(0, 1, 'Chọn chế độ tạo ảnh, dán prompt bên dưới và tạo một ảnh trước. Mở ảnh ở kích thước lớn để kiểm tra rồi dùng Download/Save của công cụ để tải file về L07; đổi tên file trong Finder hoặc File Explorer. Đổi tên node không tự lưu ảnh xuống máy.', 'Choose image generation, paste the prompt below and generate one image first. Open it at full size to check it, then use the tool’s Download/Save control to save the file into L07. Rename the downloaded file in Finder or File Explorer. Naming a node does not download its image.');
  add(0, 2, 'Trước khi gửi, kiểm tra cả văn bản kịch bản và ảnh nhân vật đã được gắn vào yêu cầu. Nếu Assistant chỉ trả mô tả bằng chữ, chuyển mô tả đó sang Image Generator cùng ảnh nhân vật. Ngoài Spaces, tải file nhân vật lên, dán kịch bản rồi thay @script/@character bằng lời chỉ rõ tài liệu nào làm nhiệm vụ gì; gõ tên file đơn thuần không đính kèm file.', 'Before sending, confirm that both script text and the character image are attached to the request. If the Assistant returns only text, pass that description and the character image to an Image Generator. Outside Spaces, upload the character file, paste the script and replace @script/@character with descriptions of their roles. Typing a filename does not attach it.');
  add(0, 3, 'Lần đầu chỉ yêu cầu shot 1. Khi đã lưu ảnh, lặp lại với shot 2 đến shot 6, dùng cùng ảnh nhân vật và bảng phác thảo. Một ảnh chỉ được nhận khi có đúng một khung cảnh, không còn đường chia ô.', 'For your first attempt, request shot 1 alone. After saving it, repeat for shots 2 through 6 with the same character and sketch references. Accept a file only when it contains one scene without panel dividers.');
  lessons[1].input = t('Dùng L07-shot-05.png đã duyệt: An và ván phải nhìn rõ, có khoảng trống phía trước. Nếu ảnh chưa có An đặt chân lên ván, tạo lại frame này trước. Các mô tả dưới đủ để làm bài; video nguồn là phần xem thêm.', 'Use your approved L07-shot-05.png: An and the board must be visible, with room ahead. If it does not show An with a foot on the board, revise that frame first. The written examples below are enough to do the exercise; the source recording is optional.');
  lessons[1].steps[0].instruction = lessons[1].steps[0].instruction.replace('Follow the recording’s order:', 'Read these ten motion examples:').replace('Theo thứ tự video:', 'Đọc mười ví dụ chuyển động:');
  add(1, 0, 'Không cần mở video nguồn để hoàn thành ghi chú. Với mỗi ví dụ, ghi bốn dòng: lực khởi đầu, thứ tự động tác, camera, phản ứng nhìn thấy. Đánh dấu đây là phân tích mô tả, không phải quan sát video đã chạy.', 'You can complete the notes without opening the recording. For each example, write four lines: initiating force, action order, camera and visible response. Label these as analysis of the description, not observations of a generated clip.');
  lessons[1].steps[1].resultText = t('Ví dụ kế hoạch, chưa phải kết quả video:\nLực: chân sau đẩy mặt đường.\nThứ tự: đẩy → nhấc chân lên ván → lướt → giảm tốc.\nCamera: theo ngang chậm, giữ cả người và ván.\nPhản ứng: An khuỵu gối để giữ thăng bằng; vạt áo đi sau thân một chút.\nNếu clip không đủ dài: chỉ làm đẩy → lướt, rồi sửa prompt cho đúng hai động tác đó.', 'Planning example, not a video result:\nForce: the rear foot pushes against the road.\nSequence: push → bring the foot onto the board → glide → slow down.\nCamera: slow lateral follow, keeping the body and board visible.\nReaction: An bends the knees to balance; the jacket follows the torso slightly later.\nIf the clip is too short: practise push → glide only, and revise the prompt to match those two actions.');
  add(1, 2, 'Mở chế độ tạo video từ ảnh; gắn file L07-shot-05.png vào ô ảnh đầu, không phải ô ảnh kết thúc. Kiểm tra hình thu nhỏ, chọn 16:9 và thời lượng được tài khoản hỗ trợ; ghi lại thời lượng trước khi bấm Generate. Dán prompt của bước này, tạo một lượt rồi tải MP4 về. Nếu không có Seedance, lưu phần chuẩn bị và ghi rõ bài tạo video chưa hoàn thành.', 'Open image-to-video and attach L07-shot-05.png as the start image, not an end image. Check the thumbnail, choose 16:9 and a duration your account supports, and record that duration before selecting Generate. Paste this step’s prompt, generate one take and download the MP4. If Seedance is unavailable, save the preparation and mark the video exercise incomplete.');
  add(2, 0, 'Tải L07-character.png vào công cụ tạo ảnh, chạy prompt bên dưới và lưu L09-reference.png. Tiền cảnh là vật gần máy nhất, trung cảnh chứa An, hậu cảnh là biển xa. Chỉ dùng ảnh mà cả ba lớp đều nhìn rõ.', 'Upload L07-character.png to the image generator, use the prompt below and save L09-reference.png. Foreground means nearest the camera, midground contains An, and background is the distant sea. Use a frame where all three layers are visible.');
  add(2, 1, 'Đọc mô tả của cả 25 kỹ thuật; chỉ cần chạy ba bài so sánh ở bước tiếp theo. Không cần mua 25 lượt tạo. Thị sai có thể kiểm tra bằng cách nhìn vị trí mép lan can so với đầu An và đường chân trời ở đầu/cuối clip.', 'Read the descriptions of all 25 techniques; generate only the three comparisons in the next step. You do not need 25 paid runs. To inspect parallax, compare the railing edge with An’s head and the horizon at the start and end of the clip.');
  add(2, 2, 'Mở từng bài kỹ thuật phía dưới, bấm Copy, tạo một video từ L09-reference.png rồi tải về trước khi thử kỹ thuật kế tiếp. Đặt tên có kỹ thuật, ví dụ L09-dolly-in-v01.mp4. Tên model trên màn hình và thời lượng phải được ghi trong settings.txt.', 'Open each selected technique below, use Copy, generate a video from L09-reference.png and download it before trying the next technique. Include the technique in its filename, such as L09-dolly-in-v01.mp4. Write the displayed model name and duration in settings.txt.');
  add(3, 0, 'Dùng L07-character.png làm đầu vào. Đây là ba file ảnh tĩnh: front, side và back; không phải một video quay vòng. Nếu giao diện chỉ cho tải một ảnh tham chiếu, bắt đầu bằng ảnh front đã duyệt.', 'Use L07-character.png as the input. The deliverable is three still files, front, side and back, rather than a rotating video. If the interface accepts only one reference, begin with the approved front view.');
  add(3, 1, 'Tên nút và cách chọn ảnh có thể khác video cũ. Tìm chức năng đính kèm/chọn tham chiếu trong giao diện hiện có, rồi kiểm tra ảnh thu nhỏ. Nếu không thấy chức năng đó, xem hướng dẫn Luma ở phần công cụ trước khi tạo; không giả định giữ Shift là đủ.', 'Labels and selection gestures may differ from the older recording. Use the attachment/reference control available in your interface and confirm the thumbnails. If it is missing, consult the linked Luma guide before generating; holding Shift alone is not proof that references are attached.');
  add(3, 3, 'Chọn chế độ tạo video từ ảnh, dùng still đã duyệt làm ảnh bắt đầu, chọn thời lượng khả dụng rồi chạy một lượt. Xem đầu và cuối clip: tay, chân và ván có giữ vị trí hợp lý không? Chỉ thử model thứ hai nếu có quyền sử dụng và đủ credit; một video đã kiểm tra vẫn là đầu ra bắt buộc.', 'Choose image-to-video, use the approved still as the start image, select an available duration and generate one take. Inspect the beginning and end for plausible hands, feet and board placement. Try a second model only if you have access and credits; one reviewed animation is the required output.');
  lessons[4].input = t('Chuẩn bị video An đã tải từ L8/L10 và một trình dựng như CapCut. Các bước dưới giải thích đủ sáu kiểu cắt; video nguồn là ví dụ xem thêm. Dùng clip tự tạo hoặc clip bạn có quyền sử dụng. Nếu chỉ có ảnh, có thể dựng bản nháp nhưng chưa kiểm tra được tính liên tục của động tác.', 'Have your downloaded An footage from L8/L10 and an editor such as CapCut ready. The written definitions explain all six cuts; the source video is an optional comparison. Use your own footage or footage you have permission to use. Stills can make a planning draft, but cannot verify action continuity.');
  add(4, 0, 'Ví dụ: jump bỏ đoạn An chờ; match nối bánh ván với mặt đồng hồ; cut on action nối cùng động tác nhấc ván; cross-cutting luân phiên An và người đang chờ cùng lúc; double cut cho thấy lại một khoảnh khắc từ góc khác; fast cutting rút ngắn nhiều shot liên tiếp. Trước khi tạo, chọn đúng ba bài jump, match và cut on action.', 'For example: a jump cut removes An’s waiting; a match cut joins a wheel to a clock; a cut on action joins the same board lift; cross-cutting alternates An with someone waiting at the same time; a double cut repeats a moment from another angle; fast cutting shortens successive shots. Your required exercises are jump, match and cut on action.');
  add(4, 1, 'Cách dựng thủ công: tạo dự án, Import clip rồi kéo xuống timeline. Timeline là dải clip theo thứ tự phát; playhead là vạch chỉ thời điểm đang xem. Tìm đoạn chờ, đặt playhead ở đầu đoạn và bấm Split; lặp lại ở cuối đoạn. Chọn mảnh giữa, xóa, rồi kéo hai mảnh còn lại sát nhau, không để khe đen. Phát qua điểm nối để thấy thời gian bị lược bỏ.', 'Manual edit: create a project, Import the clip and drag it onto the timeline. The timeline arranges clips in playback order; the playhead marks the time being viewed. Find the waiting section, place the playhead at its start and select Split; repeat at its end. Select and delete the middle piece, then bring the remaining clips together with no black gap. Play across the join to see the time omission.');
  add(4, 2, 'Tạo riêng hai shot theo hai cảnh mô tả trong prompt dưới nếu chưa có bánh ván và đồng hồ. Import cả hai, đặt shot bánh trước shot đồng hồ. Cắt điểm cuối/đầu nơi hai hình tròn gần bằng nhau và cùng vị trí; chỉnh crop nếu cần. Để hai clip nối trực tiếp, không dùng dissolve hoặc morph. Nếu chỉ dùng hai ảnh tĩnh, ghi rõ đây là bản nháp bố cục.', 'If you do not have the wheel and clock, generate separate shots from the two scene descriptions in the prompt below. Import both and place the wheel before the clock. Trim the outgoing and incoming frames where the circles have similar size and position; adjust the crop if needed. Join the clips directly without a dissolve or morph. Label an edit made from two still images as a composition draft.');
  add(4, 3, 'Cần hai góc của cùng động tác nhấc ván; nếu clip L8 không có, tạo hai shot theo prompt bước này. Dừng shot A khi tay vừa nắm ván. Tìm ở shot B khoảnh khắc nắm tương ứng rồi cắt để B tiếp tục nhấc lên. Xem một lần chậm để so bàn tay và một lần tốc độ thường để kiểm tra nhịp. Nếu B lặp lại động tác nắm, bỏ phần bị lặp.', 'You need two angles of the same board lift; if L8 footage lacks them, generate the two shots described in this step’s prompt. End A just after the hand grips the board. Find the corresponding grip in B and trim so B continues lifting. Watch slowly to compare hand position, then at normal speed to judge the rhythm. Remove a repeated grip at the beginning of B.');
  add(4, 4, 'Xuất từng bài thành MP4 riêng bằng Export, đặt tên theo kiểu cắt và lưu vào L11. Giữ tỷ lệ và tốc độ khung hình phù hợp với clip đầu vào; tăng độ phân giải không sửa được lỗi dựng. Mở file vừa xuất trong trình phát khác, xem toàn bộ rồi mới ghi nhận hoàn thành.', 'Export each exercise as its own MP4, name it after the cut and save it in L11. Keep the aspect ratio and a frame rate appropriate to the source clips; increasing resolution does not repair an edit. Open each exported file in a separate player and watch it fully before marking it complete.');
  add(5, 0, 'Không cần xem nguồn để phân biệt cỡ cảnh: dùng các định nghĩa ở trên và tưởng tượng cùng An trong từng khung. Ghi thứ bị mất khi tiến gần: toàn cảnh có đường và biển; trung cảnh có tay và thân; cận cảnh ưu tiên mặt; đặc tả chỉ giữ một chi tiết như mắt.', 'Use the definitions above to imagine the same An in each frame; the recording is optional. Note what disappears as framing gets tighter: a wide includes road and sea, a medium includes hands and torso, a close-up prioritizes the face, and an extreme close-up isolates a detail such as an eye.');
  lessons[5].steps[3].resultText = t('Mẫu mô tả dự kiến, chưa tạo video:\n0-2 giây: An trong khung từ ngực lên, nhìn về đường; máy đứng yên.\n2-5 giây: An thở ra nhẹ, giữ hướng nhìn; không đổi cỡ cảnh.\nLý do: Khung từ ngực lên đủ gần để đọc mắt và hơi thở. Đường và biển còn gợi bối cảnh. Máy đứng yên giúp tập trung vào nét mặt. Không dùng âm thanh để người xem đánh giá hình ảnh.', 'Expected-result example, not a generated video:\n0-2 seconds: An is framed from the chest up, looking toward the road; the camera is stationary.\n2-5 seconds: An exhales gently and keeps looking in the same direction; framing stays unchanged.\nRationale: Chest-up framing makes eyes and breathing readable. The road and sea still suggest the setting. A fixed camera keeps attention on the face. There is no audio, so the exercise can be judged from the image.');
  add(6, 0, 'Dùng ảnh L07-character.png và thứ tự sáu shot ở bước này. Lặp lại quy trình L7: phác sáu ô, duyệt hướng đi và ánh sáng, rồi tạo bảng tham chiếu chứa nhân vật cùng sáu ô. Bảng này là hình hướng dẫn model, không phải video cuối. Không tải bảng có bàn tay, ván hoặc trang phục sai.', 'Use L07-character.png and this step’s six-shot order. Repeat the L7 process: sketch six panels, check direction and light, then create a reference sheet containing the character and those panels. The sheet guides the model; it is not the final video. Reject a sheet with incorrect hands, board or clothing.');
  add(6, 2, 'Lần đầu giữ nguyên mẫu đã cung cấp. Lưu bằng trình soạn văn bản thuần, không dùng tài liệu định dạng Word. Khi sửa, đổi từng nội dung nằm trong dấu ngoặc kép; không xóa dấu hai chấm hoặc khoảng trắng đầu dòng. Nếu tài khoản không nhận YAML, chuyển các trường thành câu văn và lưu cả hai bản.', 'For the first attempt, keep the supplied example unchanged. Save it in a plain-text editor rather than a formatted Word document. When revising, change one quoted value at a time without deleting colons or indentation. If your tool does not accept YAML, convert its fields into prose and keep both versions.');
  add(6, 4, 'Nếu không có chế độ 15 giây, tạo sáu shot riêng rồi dựng tổng 15 giây theo các mốc đã cho. Dùng thao tác Import → timeline → Split/trim → Export ở L11. Cắt từng shot đúng khoảng 2, 2, 2, 2, 4 và 3 giây; không kéo chậm để che một shot thiếu hành động. Ghi rõ những chuyển cảnh chưa đạt thay vì đánh dấu đã hoàn thành.', 'If a 15-second mode is unavailable, generate the six shots separately and edit them to 15 seconds using L11’s Import → timeline → Split/trim → Export procedure. Trim the shots to 2, 2, 2, 2, 4 and 3 seconds. Do not slow footage merely to hide a missing action. Record any transitions that remain unsuccessful instead of marking them complete.');
  const titles: Pair[] = [
    ['L7 · Dựng cảnh trong Freepik', 'L7 · Freepik Scene Building'],
    ['L8 · Tạo chuyển động với Seedance', 'L8 · Seedance Motion Generation'],
    ['L9 · Điều khiển camera trong Kling', 'L9 · Kling Camera Control'],
    ['L10 · Nhân vật → frame → video trong Luma', 'L10 · Character → Still → Video in Luma'],
    ['L11 · Ngôn ngữ cắt dựng', 'L11 · The Language of Editing'],
    ['L12 · Cỡ cảnh và bố cục', 'L12 · Shot Sizes and Framing'],
    ['L13 · Storyboard → video điện ảnh bằng YAML', 'L13 · Storyboard → Cinematic Video with YAML'],
  ];
  const outputs: Pair[] = [
    ['Kịch bản, nhân vật, sketch sáu ô, sáu frame riêng', 'Script, character, six-panel sketch, six separate frames'],
    ["Prompt + video + giải thích 5-7 câu", "Prompt + video + 5-7 sentence rationale"],
    ['Ba video camera + prompt + lý do lựa chọn', 'Three camera videos + prompts + rationale'],
    ['Bộ góc nhìn nhân vật + frame điện ảnh + animation', 'Character turnaround + cinematic still + animation'],
    ["Ba chuỗi cắt dựng + giải thích 1-2 câu mỗi chuỗi", "Three edited sequences + 1-2 sentences each"],
    ['Prompt 5 giây, hai khối thời gian, không âm thanh + giải thích', 'Silent five-second prompt, two time blocks + rationale'],
    ['Storyboard sáu shot + YAML + video 15 giây + review', 'Six-shot storyboard + YAML + 15-second video + review'],
  ];
  return {
    courseTitle: t('Quy trình làm phim AI & ngôn ngữ camera', 'AI Cinema Workflow & Camera Language'),
    workbookName: 'GenYZ-AI-Cinema-Workflow',
    source: { title: "IDALL Lite · Step 4 · Lessons 7-13", author: 'IDALL · Loom: Darren Maen', href: `${classroom}?md=${sources[0]}`, note: t('Workshop này được biên soạn từ bài học và video nguồn; An là ví dụ thực hành mới. Các liên kết nguồn có thể cần tài khoản Skool. Đây không phải khóa học chính thức của nhà cung cấp công cụ.', 'This workshop is adapted from the classroom lessons and source recordings; An is an original practice example. Source links may require Skool access. It is not an official course from the tool providers.') },
    durationLabel: t("7 bài · video nguồn 67 phút 26 giây · dự kiến thực hành 7-10 giờ", "7 lessons · 67m 26s of source recordings · estimated practice 7-10 hours"),
    syllabus: lessons.map((lesson, i) => ({ id: lesson.id, title: pick(titles[i]), phase: i < 2 ? 0 : i < 6 ? 1 : 2, minutes: [65,60,75,60,60,45,90][i], summary: lesson.goal, output: pick(outputs[i]) })),
    phases: [t('Dựng cảnh và chuyển động', 'Build scenes and motion'), t('Camera, hình ảnh và cắt dựng', 'Camera, images and editing'), t('Tổng hợp bằng storyboard và YAML', 'Combine storyboard and YAML')],
    tools: [
      { name: 'Freepik Spaces', href: 'https://www.freepik.com/', purpose: t('Node kịch bản, nhân vật, storyboard; thử camera bằng Kling.', 'Script, character and storyboard nodes; Kling camera tests.') },
      { name: 'Seedance', href: 'https://www.capcut.com/', purpose: t("Tạo chuyển động và chuỗi shot; nguồn L11-12 dùng trong CapCut. Ghi lại model thực tế.", "Motion and shot sequences; L11-12 demonstrate it in CapCut. Log the actual model used.") },
      { name: 'Luma', href: 'https://lumalabs.ai/', purpose: t('Từ bộ góc nhìn đến frame và animation trong cuộc hội thoại.', 'Character views, cinematic stills and animation within a conversation.') },
      { name: 'Spaces · Help', href: 'https://www.freepik.com/ai/docs/introduction-to-spaces', purpose: t('Hướng dẫn hiện tại về canvas và cách thêm node. Tên thương hiệu/giao diện có thể khác video nguồn.', 'Current canvas and node-creation guide. Branding and interface labels may differ from the source recording.') },
      { name: 'Luma · Learning Center', href: 'https://lumalabs.ai/learning-center', purpose: t('Tra cách thao tác khi màn hình hiện tại khác ví dụ cũ.', 'Find the current workflow when your screen differs from an older example.') },
      { name: 'CapCut · Split and export', href: 'https://www.capcut.com/resource/split-video-into-parts', purpose: t('Hướng dẫn Import, Split trên timeline và Export cho bài L11.', 'Import, timeline Split and Export instructions for L11.') },
    ],
    glossary: [
      ['Shot', t('Một cú máy hoặc đơn vị hình ảnh liên tục giữa hai điểm cắt.', 'A continuous camera view or visual unit between edits.')],
      ['Frame / storyboard', t('Một khung hình / bản phân cảnh bằng hình.', 'A single image / a visual shot plan.')],
      ['Continuity', t('Tính liên tục của nhận diện, hành động, không gian và ánh sáng.', 'Consistency of identity, action, space and lighting.')],
      ['Parallax', t('Thị sai: vật gần và xa đổi vị trí tương đối khi máy di chuyển.', 'Relative displacement of near and far objects as the camera moves.')],
      ['Cut on action / match on action', t('Cắt nối trong cùng động tác để giữ chuyển động liên tục.', 'An edit within the same action that preserves movement continuity.')],
      ['Graphic match cut', t('Cắt nối nhờ hình dáng, vị trí hoặc bố cục tương đồng.', 'An edit connecting similar shapes, positions or compositions.')],
      ['YAML', t('Văn bản có cấu trúc bằng key, value và thụt lề; trong bài này là cách viết prompt.', 'Text structured through keys, values and indentation; used here as a prompting format.')],
    ],
    preparation: {
      title: t('Bắt đầu · Từ cảnh đầu tiên đến video 15 giây', 'Start · From your first scene to a 15-second video'),
      intro: t('Bắt đầu với sáu shot, rồi đi qua chuyển động, camera, Luma, cắt dựng và cỡ cảnh trước khi làm video YAML 15 giây. Học khái niệm trước, sau đó làm bài tập và giữ các phiên bản để so sánh.', 'Start with six shots, then move through motion, camera, Luma, editing and framing before making a 15-second YAML-directed video. Learn the concept first, then practice and keep versions for comparison.'),
      steps: [
        { heading: t('Chọn lộ trình lần đầu', 'Choose your first pass'), text: t('Học lần lượt bảy bài, bắt đầu ở L7; không cần khóa học trước đó. Xem liên kết nguồn nếu muốn đối chiếu, nhưng làm theo hướng dẫn và prompt tại đây. 25 bài camera là thư viện lựa chọn: L9 chỉ cần ba bài. Nếu thiếu quyền truy cập công cụ hoặc credit, tiếp tục viết kế hoạch và prompt; ghi rõ phần video chưa tạo, không đánh dấu yêu cầu video là đạt.', 'Work through the seven lessons in order, starting at L7; no earlier course is required. Source links are optional comparisons: follow the instructions and prompts here. The 25 camera labs are a library of choices; L9 requires three. If a tool or credits are unavailable, continue planning and writing prompts, but mark video outputs as not generated and leave video checks incomplete.') },
        { heading: t('1 · Chuẩn bị công cụ và thư mục', '1 · Prepare tools and folders'), text: t('Kiểm tra tài khoản và model đang có trong Freepik, Seedance/CapCut và Luma. Tạo thư mục L07…L13; mỗi thư mục lưu reference, prompt, thiết lập, kết quả và ghi chú. Giao diện hoặc model trong video nguồn có thể không giống tài khoản của bạn hiện nay.', 'Check account access and the models currently available in Freepik, Seedance/CapCut and Luma. Create L07…L13 folders for references, prompts, settings, outputs and reviews. The interfaces or models shown in the recordings may differ from your account today.') },
        { heading: t('2 · Giữ một nhân vật xuyên suốt', '2 · Keep one character throughout'), text: t('Ví dụ An thống nhất mũ ngọc lam, áo kem, quần xám than, giày trắng và ván gỗ bánh đen. Có thể dùng nhân vật của bạn; thay nhất quán mọi prompt và tạo reference trước. Không dùng @image1 như tên file nếu chưa gắn ảnh thật.', 'An’s teal helmet, cream jacket, charcoal trousers, white shoes and wood board with black wheels provide a consistent example. You may substitute your own character consistently across prompts after making a reference. @image1 must point to an actual attached image.') },
        { heading: t('3 · Phân biệt nguồn và bài thực hành', '3 · Separate source and practice'), text: t('Mỗi bài đều có liên kết để đối chiếu nguồn. L10 thực tế dạy Luma; L11 dạy sáu kỹ thuật cắt; L12 yêu cầu clip không âm thanh. Prompt GenYZ là ví dụ mới, chưa chạy thử ở cả hai ngôn ngữ; tiêu chí review không phải kết quả đã tạo.', 'Each lesson includes a link back to its source. L10 actually teaches Luma; L11 teaches six cuts; L12 assigns a silent clip. GenYZ prompts are original examples, untested in both languages; review targets are not generated outputs.') },
        { heading: t('4 · Dùng bản dịch và workbook', '4 · Use translations and the workbook'), text: t('Có prompt tiếng Việt và tiếng Anh tương ứng. Dùng Copy để lấy toàn bộ nội dung kể cả khi đang thu gọn. Với YAML, giữ key tiếng Anh, dấu cách đầu dòng và toàn bộ sáu shot; workbook lưu nguyên khối để kiểm tra lại.', 'Equivalent Vietnamese and English prompts are available. Copy retrieves the full text even when collapsed. For YAML, retain English keys, leading spaces and all six shots; the workbook retains the complete block for inspection.') },
      ],
      toolPaths: [{ title: t('Thao tác chung trước lượt tạo đầu', 'Before your first generation'), steps: [
        t('Tạo một thư mục AI-Cinema bằng Finder/File Explorer, rồi tạo các thư mục L07 đến L13. Trong mỗi thư mục, tạo inputs, prompts, takes và review. Khi bài nói “Lưu”, đó là file bạn tải xuống hoặc tự tạo; nút hoàn thành không tạo file hộ bạn.', 'Create an AI-Cinema folder in Finder/File Explorer, then folders L07 through L13. Inside each, create inputs, prompts, takes and review. “Save” names a file you download or create yourself; marking a lesson complete does not create it.'),
        t('Dùng công cụ chat để viết kế hoạch; dùng chế độ tạo ảnh cho PNG/JPG; dùng chế độ tạo video cho MP4. Trước khi bấm tạo, kiểm tra ảnh đã gắn, tỷ lệ, thời lượng nếu có và chi phí hiển thị. Tên model trong bài nguồn là thông tin lịch sử, không bảo đảm tài khoản của bạn có model đó.', 'Use chat for plans, image generation for PNG/JPG, and video generation for MP4. Before generating, check attached images, aspect ratio, duration where applicable and the displayed cost. Model names from the source recording are historical references, not a guarantee that your account offers them.'),
        t('Đặt tên lượt đầu v01. Khi sửa, lưu v02 riêng; ghi “đã đổi gì, kết quả ra sao, dùng file nào ở bước sau”. Với phần nộp bài, gom file vào thư mục được yêu cầu; trang này không có nút tải bài nộp. Bạn có thể tự kiểm tra theo checklist.', 'Name the first take v01. Save a revision as v02 and note what changed, what happened and which file the next step should use. “Submit” means collect the requested files; this page has no assignment-upload button. Use the checklist for your own review.'),
      ] }],
      note: t('Thời gian thực hành chỉ là ước tính, chưa gồm thời gian chờ tạo hoặc chạy lại. Nộp đúng yêu cầu từng bài trước khi chuyển tiếp. Tạo video thực tế có thể tiêu tốn credit; workshop không tự chạy hay mua lượt tạo.', 'Practice time is an estimate excluding generation queues and retries. Complete each lesson’s submission before progressing. Actual generation may consume credits; the workshop does not automatically generate or purchase runs.'),
    },
    lessons,
  };
}
